/// A struct whose first field is `size_t size`, which the library reads to
/// learn which version of the struct the caller compiled against.
pub(crate) trait SizedStruct: Default {
    fn size_mut(&mut self) -> &mut usize;
}

/// Zero-initializes a sized struct and sets its `size` field, like the
/// header's `GHOSTTY_INIT_SIZED`.
pub(crate) fn sized<T: SizedStruct>() -> T {
    let mut value = T::default();
    *value.size_mut() = size_of::<T>();
    value
}

/// Packs a mode like the header's inline `ghostty_mode_new`: bits 0-14 hold
/// the value and bit 15 marks an ANSI mode.
pub(crate) const fn mode(value: u16, ansi: bool) -> GhosttyMode {
    let flag: u16 = if ansi { 1 << 15 } else { 0 };
    (value & 0x7fff) | flag
}
